#!/usr/bin/env python3
"""Generate the public-series documents on PUMP from the API responses saved in data/raw/ (nothing typed by hand):
  docs/pumpfun/02-public-series-2024-2026.md   fees, revenue, take rate and product mix since March 2024; weekly 2026; the launchpad pie
  docs/pumpfun/04-valuation-and-derivatives.md price, market cap, supply, multiples, comparables, target grid, buyback coverage, funding, open interest
Run from the repository root:  python3 scripts/report_pumpfun_public.py"""
import json, os, glob, statistics, collections, datetime as dt
R = 'data/raw'
def load(name):
    with open(os.path.join(R, name)) as f: return json.load(f)
def day(t): return dt.datetime.fromtimestamp(t, dt.timezone.utc).date()
def daily(o): return {day(t): float(v or 0) for t, v in o['totalDataChart']}
def monthly(d):
    m = collections.defaultdict(float)
    for k, v in d.items(): m[(k.year, k.month)] += v
    return m
def weekly(d):
    w = collections.defaultdict(float)
    for k, v in d.items(): w[k - dt.timedelta(days=k.weekday())] += v
    return w
def M(x): return f'{x/1e6:,.1f}'
def pct(x, n=0): return '—' if x is None else f'{100*x:.{n}f} %'
def mon(y, m): return dt.date(y, m, 1).strftime('%b %Y')
class Doc:
    def __init__(self): self.L = []
    def h(self, x): self.L += [x, '']
    def table(self, header, rows):
        self.L.append('| ' + ' | '.join(header) + ' |'); self.L.append('|' + '---|' * len(header))
        for r in rows: self.L.append('| ' + ' | '.join(str(c) for c in r) + ' |')
        self.L.append('')
    def write(self, path):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'w') as f: f.write('\n'.join(self.L))
        print('ok', path, len(' '.join(self.L).split()), 'words')
today = dt.date.today().isoformat()
fees_o = load('llama_pump_fees.json'); rev_o = load('llama_pump_revenue.json')
fees, rev = daily(fees_o), daily(rev_o); mf, mr = monthly(fees), monthly(rev); wf, wr = weekly(fees), weekly(rev)
last = max(rev)
# product breakdown
pb = collections.defaultdict(lambda: collections.defaultdict(float))
for t, dd in fees_o['totalDataChartBreakdown']:
    for chain, prods in dd.items():
        for p, v in prods.items(): pb[day(t)][p] += v
prods = ['pump.fun', 'PumpSwap', 'Terminal', 'pump.fun Mobile App']
def pbm(y, m, p): return sum(v.get(p, 0) for k, v in pb.items() if (k.year, k.month) == (y, m))
def pbw(w, p): return sum(v.get(p, 0) for k, v in pb.items() if k - dt.timedelta(days=k.weekday()) == w)

# ======================= 02: public series =======================
D = Doc()
D.h('# PUMP in the public series, March 2024 – October 2026\n')
D.h(f'*Generated by `scripts/report_pumpfun_public.py` on {today} from the DefiLlama responses saved in `data/raw/` (`llama_pump_fees.json`, `llama_pump_revenue.json`, breakdown by product; `llama_lp_*_fees.json` for the other launchpads), accessed Oct 21, 2026. Fees = what traders pay; revenue = what pump.fun keeps; take rate = revenue ÷ fees. Weeks start on Monday (ISO). The last day is {last.isoformat()}. This is the long view the collector cannot give: the collector measures the crowd position by position for 16 days (`03-sixteen-days-tick-level.md`); these series give 32 months of fees and revenue, but say nothing about who paid them.*')

D.h('## 1. Month by month, March 2024 → October 2026\n')
rows = []
months = sorted(k for k in mr if k >= (2024, 3))
for (y, m) in months:
    f, r = mf[(y, m)], mr[(y, m)]
    rows.append([mon(y, m) + (' (to Oct 20)' if (y, m) == (2026, 10) else ''), M(f), M(r), pct(r / f if f else None), M(pbm(y, m, 'pump.fun')), M(pbm(y, m, 'PumpSwap')), M(pbm(y, m, 'Terminal') + pbm(y, m, 'pump.fun Mobile App')), pct(pbm(y, m, 'pump.fun') / f if f else None)])
D.table(['month', 'fees $M', 'revenue $M', 'take rate', 'launchpad (curve) fees $M', 'PumpSwap fees $M', 'Terminal + app fees $M', 'curve share of fees'], rows)
pk1 = max((k for k in months if k < (2025, 6)), key=lambda k: mr[k]); tr1 = min((k for k in months if pk1 < k < (2025, 9)), key=lambda k: mr[k])
pk2 = max((k for k in months if (2025, 6) <= k < (2026, 3)), key=lambda k: mr[k]); tr2 = min((k for k in months if pk2 < k < (2026, 8)), key=lambda k: mr[k])
pk3 = max((k for k in months if (2026, 3) <= k < (2026, 10)), key=lambda k: mr[k])
D.h(f'**Three peaks, two collapses (revenue).** First peak {mon(*pk1)} at ${M(mr[pk1])}M → {mon(*tr1)} ${M(mr[tr1])}M ({100*(mr[tr1]/mr[pk1]-1):+.0f} %). Second peak {mon(*pk2)} at ${M(mr[pk2])}M → {mon(*tr2)} ${M(mr[tr2])}M ({100*(mr[tr2]/mr[pk2]-1):+.0f} %). Third peak {mon(*pk3)} at ${M(mr[pk3])}M; October 1–20: ${M(mr[(2026,10)])}M, i.e. ≈ ${M(mr[(2026,10)]*31/20)}M at the 20-day pace.')
base = sum(mr[(2026, m)] for m in range(2, 7)) / 5 * 12; ttm = sum(mr[k] for k in months if (2025, 10) <= k <= (2026, 9)); prev = sum(mr[k] for k in months if (2024, 10) <= k <= (2025, 9))
D.h(f'**Revenue bases (annualised).** February–June 2026 average: ${M(base)}M a year. June 2026 trough: ${M(mr[(2026,6)]*12)}M. Trailing twelve months (Oct 2025 – Sep 2026): ${M(ttm)}M, against ${M(prev)}M for the twelve months before ({100*(ttm/prev-1):+.0f} %). Last 30 days to {last.isoformat()}: ${M(sum(rev[k] for k in rev if last - dt.timedelta(days=29) <= k <= last) * 365 / 30)}M run-rate.')
D.h('**The take rate.** ' + '; '.join(f'{mon(*k)} {pct(mr[k]/mf[k])}' for k in [(2025,1),(2025,4),(2025,7),(2025,9),(2025,12),(2026,3),(2026,6),(2026,8),(2026,9),(2026,10)]) + '. The cut from 100 % came in two steps: the creator-reward and PumpSwap liquidity-provider share from spring 2025 (a mix effect: PumpSwap fees are shared with liquidity providers), and Project Ascend in September 2025; since the token launch (July 2025) the rate went from 58 % to 32–36 %.')

D.h('## 2. Week by week, 2026\n')
rows = []
weeks = sorted(w for w in wr if w >= dt.date(2026, 1, 5) and w <= last - dt.timedelta(days=6))
for w in weeks:
    f, r = wf[w], wr[w]; rows.append([w.isoformat(), M(f), M(r), pct(r / f if f else None), M(pbw(w, 'pump.fun')), M(pbw(w, 'PumpSwap')), f'{100*(r/wr[w-dt.timedelta(days=7)]-1):+.0f} %' if wr.get(w - dt.timedelta(days=7)) else '—'])
D.table(['week of', 'fees $M', 'revenue $M', 'take rate', 'curve fees $M', 'PumpSwap fees $M', 'revenue w/w'], rows)
pkw = max(weeks, key=lambda w: wr[w]); l7 = sum(rev[k] for k in rev if last - dt.timedelta(days=6) <= k <= last)
wc_=collections.defaultdict(float)
for k,v in pb.items(): wc_[k-dt.timedelta(days=k.weekday())]+=v.get('pump.fun',0)
_wk=[w for w in sorted(wc_) if w<=last-dt.timedelta(days=6)]; _ch=[(w, wc_[w]/wc_[p]-1) for p,w in zip(_wk,_wk[1:]) if wc_[p]>0][-40:]
D.h(f'**Base rate of one-week falls (curve fees, last 40 full weeks):** {sum(1 for _,c in _ch if c<=-0.14)} weeks at −14 % or worse, {sum(1 for _,c in _ch if c<=-0.26)} at −26 % or worse; the worst was the week of {min(_ch,key=lambda x:x[1])[0].isoformat()} ({100*min(c for _,c in _ch):+.0f} %). A one-week drop of the size seen on October 13–19 is therefore not rare; the paper rests on the composition and the same-chain control, not on one week.')
D.h(f'Peak week: {pkw.isoformat()} at ${M(wr[pkw])}M of revenue; last full 7 days to {last.isoformat()}: ${M(l7)}M ({100*(l7/wr[pkw]-1):+.0f} %). Largest one-week drop in 2026: ' + max(((w, wr[w]/wr[w-dt.timedelta(days=7)]-1) for w in weeks if wr.get(w-dt.timedelta(days=7))), key=lambda x: -x[1])[0].isoformat() + f' ({100*min((wr[w]/wr[w-dt.timedelta(days=7)]-1) for w in weeks if wr.get(w-dt.timedelta(days=7))):+.0f} %).')

# time to -50 % after each revenue peak week (full weeks only)
_ws=[w for w in sorted(wr) if w<=last-dt.timedelta(days=6)]
_pks=[max((w for w in _ws if w<dt.date(2025,6,1)), key=lambda w: wr[w]), max((w for w in _ws if dt.date(2025,6,1)<=w<dt.date(2026,3,1)), key=lambda w: wr[w]), max((w for w in _ws if w>=dt.date(2026,3,1)), key=lambda w: wr[w])]
_lines=[]
for _pk in _pks:
    _after=[w for w in _ws if w>_pk]; _half=next((w for w in _after if wr[w]<=0.5*wr[_pk]), None)
    _lines.append(f"peak week {_pk.isoformat()} (${M(wr[_pk])}M) → first full week at −50 %: " + (f"{_half.isoformat()}, {(_half-_pk).days} days" if _half else f"not yet (last full week {_ws[-1].isoformat()}, {100*(wr[_ws[-1]]/wr[_pk]-1):+.0f} %)"))
D.h('**Time to −50 % after each revenue peak week (full weeks only):** ' + '; '.join(_lines) + '.')
_bd=[d for d in pb if dt.date(2026,2,1)<=d<=dt.date(2026,6,30)]; _oc=[d for d in pb if last-dt.timedelta(days=6)<=d<=last]
D.h(f"**Where the crowd's spending stands against the pre-mania base:** curve fees per day {statistics.mean(pb[d].get('pump.fun',0) for d in _bd)/1e6:.2f}M (Feb–Jun 2026) against {statistics.mean(pb[d].get('pump.fun',0) for d in _oc)/1e6:.2f}M over the last 7 days (×{statistics.mean(pb[d].get('pump.fun',0) for d in _oc)/statistics.mean(pb[d].get('pump.fun',0) for d in _bd):.2f}); all products {statistics.mean(sum(pb[d].values()) for d in _bd)/1e6:.2f}M against {statistics.mean(sum(pb[d].values()) for d in _oc)/1e6:.2f}M (×{statistics.mean(sum(pb[d].values()) for d in _oc)/statistics.mean(sum(pb[d].values()) for d in _bd):.2f}). The crowd is still spending about twice the pre-mania base: the thesis is that it reverts, not that it has reverted.")
_pkps=max((w for w in sorted(wk_ps) if dt.date(2026,6,1)<=w<=last-dt.timedelta(days=6)), key=lambda w: wk_ps[w]) if False else None
D.h('## 3. The launchpad pie, launchpads only (16 venues, all chains)\n')
D.h('DefiLlama\'s launchpad category: the 16 venues with more than $0.3M of fees in the 30 days to October 21, 2026, each counted on its launchpad fees only (for pump.fun, the bonding curve: not PumpSwap, the Terminal or the app). The dashed series of Fig. D3 in the paper (pump.fun counted with all its products) is given in the last column.')
lps = {os.path.basename(f)[9:-10]: weekly(daily(load(os.path.basename(f)))) for f in glob.glob(os.path.join(R, 'llama_lp_*_fees.json'))}
rows = []
for w in sorted(w for w in lps['pump.fun'] if dt.date(2026, 6, 1) <= w <= dt.date(2026, 10, 12)):
    tot = sum(lps[n].get(w, 0) for n in lps); pf = lps['pump.fun'].get(w, 0); others = tot - pf
    top = sorted(((lps[n].get(w, 0), n) for n in lps if n != 'pump.fun'), reverse=True)[:2]
    rows.append([w.isoformat(), M(tot), M(pf), pct(pf / tot if tot else None), ', '.join(f'{n} {M(v)}' for v, n in top), pct(wf.get(w, 0) / (others + wf.get(w, 0)) if tot else None)])
D.table(['week of', 'pie $M', 'pump.fun launchpad $M', 'share', 'two largest others $M', 'share counting all pump.fun products'], rows)

D.h('## 4. What these series can and cannot say\n')
D.h('They can say how much the crowd paid and how much pump.fun kept, every day since March 2024, and how the product mix moved. They cannot say how many buyers paid it, what each one made, how long they stayed, or whether the operators were the same: that is what the collector measures, and only for the days it ran. The honest join between the two is in `00-README.md`.')
D.write('docs/pumpfun/02-public-series-2024-2026.md')

# ======================= 04: valuation and derivatives =======================
V = Doc()
coin = load('cg_pump_coin.json'); md = coin['market_data']; chart = load('cg_pump_chart.json')
px = {day(t/1000): p for t, p in chart['prices']}; mc = {day(t/1000): m for t, m in chart['market_caps']}
price = chart['prices'][-1][1]; mcap = chart['market_caps'][-1][1]; circ = md['circulating_supply']; tot = md['total_supply']; mx = md['max_supply']
r30 = sum(rev[k] for k in rev if last - dt.timedelta(days=29) <= k <= last); rr = r30 * 365 / 30; r90 = sum(rev[k] for k in rev if last - dt.timedelta(days=89) <= k <= last) * 365 / 90
V.h('# PUMP: price, supply, multiples, comparables, derivatives\n')
V.h(f'*Generated by `scripts/report_pumpfun_public.py` on {today} from `data/raw/` (CoinGecko `cg_pump_coin.json`, `cg_pump_chart.json`, `cg_comps.json`, accessed Oct 21, 2026; DefiLlama `llama_comp_*`; Binance `binance_pump_funding.json`, `binance_pump_oi.json`; Hyperliquid `hl_meta.json`). Every number of the paper\'s valuation that comes from a public source is recomputed here; the unlock schedule, the ICO price and the buyback policy come from the Blockworks Token Transparency filing and pump.fun\'s token page, cited in the paper and not archived in this repository.*')
V.h('## 1. Price, market cap, supply\n')
V.table(['item', 'value', 'source'], [
    ['Price', f'${price:.5f} (CoinGecko tick, {chart["prices"][-1][0]//1000 and dt.datetime.fromtimestamp(chart["prices"][-1][0]/1000, dt.timezone.utc).strftime("%Y-%m-%d %H:%M")} UTC)', 'cg_pump_chart.json'],
    ['Market cap', f'${mcap/1e9:.2f}B', 'cg_pump_chart.json'],
    ['Circulating supply', f'{circ/1e9:.1f}B', 'cg_pump_coin.json'],
    ['Total supply (after burns)', f'{tot/1e9:.1f}B', 'cg_pump_coin.json'],
    ['Max supply', f'{mx/1e9:.0f}B', 'cg_pump_coin.json'],
    ['Burned to date', f'{100*(1-tot/mx):.1f} % of max supply ({(mx-tot)/1e9:.1f}B)', 'computed'],
    ['FDV (total supply × price)', f'${tot*price/1e9:.2f}B', 'computed'],
    ['Revenue, last 30 days', f'${M(r30)}M (run-rate ${M(rr)}M/yr); 90-day annualised ${M(r90)}M', 'llama_pump_revenue.json'],
    ['Multiple, market cap / run-rate revenue', f'{mcap/rr:.2f}×', 'computed'],
    ['Multiple on 90-day revenue', f'{mcap/r90:.2f}×', 'computed'],
    ['FDV / run-rate revenue', f'{tot*price/rr:.2f}×', 'computed'],
])
V.h('## 2. The multiple over the last year, month by month\n')
V.h('Market cap at each month-end divided by the revenue of the trailing 30 days annualised: what the market paid for a dollar of revenue, before and during the mania.')
rows = []
pdays = sorted(px)
for (y, m) in sorted({(k.year, k.month) for k in pdays}):
    last_d = max(k for k in pdays if (k.year, k.month) == (y, m))
    r30m = sum(rev[k] for k in rev if last_d - dt.timedelta(days=29) <= k <= last_d) * 365 / 30
    rows.append([mon(y, m) + ('' if last_d.day >= 28 else f' (to {last_d.day})'), f'${px[last_d]:.5f}', f'${mc[last_d]/1e9:.2f}B', M(r30m), f'{mc[last_d]/r30m:.2f}×' if r30m else '—'])
V.table(['month-end', 'price', 'market cap', 'trailing-30d revenue, annualised $M', 'multiple'], rows)
lo = min(pdays, key=lambda k: px[k]); hi = max(pdays, key=lambda k: px[k])
V.h(f'Range of the year: low ${px[lo]:.5f} on {lo.isoformat()}, high ${px[hi]:.5f} on {hi.isoformat()}; month-end October 2025 ${px[max(k for k in pdays if (k.year,k.month)==(2025,10))]:.5f} → June 2026 ${px[max(k for k in pdays if (k.year,k.month)==(2026,6))]:.5f} ({100*(px[max(k for k in pdays if (k.year,k.month)==(2026,6))]/px[max(k for k in pdays if (k.year,k.month)==(2025,10))]-1):+.0f} %).')
V.h('## 3. Comparables (October 21, 2026)\n')
V.h('Market cap from CoinGecko; fees and revenue of the last 30 days from DefiLlama (`total30d`); multiple = market cap ÷ (30-day revenue × 365/30). Windows end on the provider\'s last day, October 20–21.')
comps = {c['symbol']: c for c in load('cg_comps.json')}
rows = []
for name, sym in [('pump.fun', 'pump'), ('Pons', 'pons'), ('Raydium', 'ray'), ('Jupiter', 'jup'), ('Hyperliquid', 'hype'), ('Virtuals Protocol', None), ('Clanker', 'clanker')]:
    key = {'pump.fun': 'pump', 'Pons': 'pons', 'Raydium': 'raydium', 'Jupiter': 'jupiter', 'Hyperliquid': 'hyperliquid', 'Virtuals Protocol': 'virtuals-protocol', 'Clanker': 'clanker'}[name]
    try: rv = load(f'llama_comp_{key}_rev.json'); fe = load(f'llama_comp_{key}_fees.json')
    except FileNotFoundError: continue
    r30c = rv.get('total30d') or 0; f30c = fe.get('total30d') or 0; c = comps.get(sym) if sym else None
    mcc = c['market_cap'] if c else None
    rows.append([name, f'${mcc/1e9:.2f}B' if mcc else '—', M(f30c), M(r30c), pct(r30c / f30c if f30c else None), f'{mcc/(r30c*365/30):.1f}×' if (mcc and r30c) else '—'])
V.table(['protocol', 'market cap', 'fees 30d $M', 'revenue 30d $M', 'take rate', 'market cap / annualised 30d revenue'], rows)
V.h('## 4. Target grid: revenue base × multiple\n')
bases = [('June-2026 trough', mr[(2026, 6)] * 12), ('Feb–Jun 2026 average', base), ('Trailing 12 months', ttm), ('Last full week ×52', wr[max(w for w in wr if w <= last - dt.timedelta(days=6))] * 52), ('Peak run-rate (30 days to Oct 20)', rr)]
mults = [('1.9× (June 2026 month-end)', 1.9), (f'{mcap/rr:.2f}× (today, 30-day basis)', mcap / rr), (f'{mcap/r90:.2f}× (today, 90-day basis)', mcap / r90)]
V.table(['revenue base ↓ / multiple →'] + [m[0] for m in mults], [[f'{n}, ${M(b)}M/yr'] + [f'${mult*b/circ:.4f} ({100*(mult*b/circ/price-1):+.0f} %)' for _, mult in mults] for n, b in bases])
V.h(f'The paper\'s target: {mcap/rr:.2f}× × ${M(base)}M ÷ {circ/1e9:.1f}B = ${mcap/rr*base/circ:.5f}, rounded to $0.0022 ({100*(0.0022/price-1):+.0f} % from ${price:.5f}).')
V.h('## 5. Supply schedule (typed from the public sources cited in the paper: Blockworks Token Transparency filing, Tokenomist, 4Pillars, DropsTab; not archived in data/raw)\n')
V.table(['item', 'value', 'source'], [
    ['Max supply', '1,000B, fixed (mint authority null)', 'Blockworks filing'],
    ['Allocation', 'ICO 33 % (330B, all unlocked at launch, sold at $0.004: 180B private, 150B public); community 24 % (linear over 48 months); team 20 % (200B); investors 13 % (130B); livestream 3 %; liquidity 2.6 %; ecosystem 2.4 %; foundation 2 %', 'Tokenomist, DropsTab'],
    ['Team and investors: cliff', '12-month cliff on July 12, 2026: 82.5B unlocked (25 % of the 330B), ≈ 20 % of the then-circulating supply', 'Tokenomist, TokenPost'],
    ['Team and investors: monthly', '6.875B a month (team 4.17B + investors 2.71B) around the 12th, until July 2029 (48 months linear); ≈ $32.6M at $0.00474, ≈ 1.5 % of circulating supply each; next: Nov 12, Dec 12, 2026, Jan 12, 2027…', '4Pillars, KuCoin news'],
    ['What insiders did with the cliff', '52.7B transferred on July 14 to 84 addresses; 7.6 % sold within 27 days (4.03B, $6.97M); 62 wallets with no sale', '4Pillars'],
    ['Against it: the buyback', f'50 % of revenue to buy-back-and-burn until April 28, 2027 (changeable by one address, no timelock); $490.7M bought back since launch; last 30 days $29.5M observed against ≈ $32.6M unlocked; at the Feb–Jun base ({M(base)}M/yr) ≈ $16.6M a month of buybacks against $32.6M unlocked', 'pump.fun token page, Blockworks filing, DefiLlama'],
])
V.h('## 6. Buyback coverage and the reverse check\n')
V.h(f'**Buyback-coverage price** (no multiple): the price at which 50 % of annual revenue buys back exactly the annual insider issuance of 82.5B tokens (6.875B a month, Blockworks filing): P = 0.5 × revenue ÷ 82.5B. Run-rate ${M(rr)}M → ${0.5*rr/82.5e9:.4f}; Feb–Jun base ${M(base)}M → ${0.5*base/82.5e9:.4f}; June trough → ${0.5*mr[(2026,6)]*12/82.5e9:.4f}. Both the target and this price are linear in revenue.')
fdv = tot * price; flow = 0.5 * rr
V.h(f'**Reverse check (fully diluted).** FDV ${fdv/1e9:.2f}B ÷ annual holder flow (50 % × ${M(rr)}M = ${M(flow)}M) = {fdv/flow:.1f}×. At a 25 % discount rate, flat peak flows are worth ${flow/0.25/1e9:.2f}B of FDV ({100*(flow/0.25/fdv-1):+.0f} %); base flows (50 % × ${M(base)}M) ${0.5*base/0.25/1e9:.2f}B ({100*(0.5*base/0.25/fdv-1):+.0f} %). The revenue that justifies today\'s FDV with no growth: ${fdv*0.25/0.5/1e9:.2f}B a year.')
V.h('## 7. Retests of the stops on the public series\n')
_allw=sorted(w for w in wr if w<=last-dt.timedelta(days=6)); _run=0; _hits=[]
for w in _allw:
    _run=_run+1 if wr[w]>=16e6 else 0
    if _run==4: _hits.append(w.isoformat())
_sol={day(t/1000): p for t,p in load('cg_sol_chart.json')['prices']}; _days=sorted(d for d in px if d in _sol); _ratio={d: px[d]/_sol[d] for d in _days}; _n=_hit=0
for i,d in enumerate(_days):
    end=d+dt.timedelta(days=180)
    if end>_days[-1]: break
    _n+=1; _hit+= max(_ratio[x] for x in _days[i:] if x<=end) >= 2*_ratio[d]
_n2=_h2=0
for i,d in enumerate(_days):
    end=d+dt.timedelta(days=180)
    if end>_days[-1]: break
    _n2+=1; _h2+= min(px[x] for x in _days[i:] if x<=end) <= 0.5*px[d]
V.h(f'**Base rate of the target move:** over the same 365 days, PUMP fell 50 % or more within 180 days from {_h2} of {_n2} starting days ({100*_h2/_n2:.0f} %): the token moves both ways, the thesis is about the direction and the stops about the size.')
V.h(f'**Thesis stop** (weekly revenue ≥ $16M for four consecutive weeks): reached {len(_hits)} time(s) in {len(_allw)} weeks since March 2024' + (f' (the run ended on {_hits[-1]})' if _hits else '') + '. **Catastrophe stop** (PUMP/SOL ratio ×2 from entry): over the 365 days of CoinGecko data, the ratio doubled within 180 days in ' + f'{_hit} of {_n} starting days ({100*_hit/_n:.0f} %), against the paper\'s rough 38 % with no drift and 12 % with the drift the thesis predicts.')
V.h('## 8. Derivatives: funding and open interest\n')
fr = sorted(load('binance_pump_funding.json'), key=lambda x: x['fundingTime']); tmax = fr[-1]['fundingTime']
def ann(days):
    s = [float(x['fundingRate']) for x in fr if x['fundingTime'] >= tmax - days * 86400 * 1000]
    return f'{100*statistics.mean(s)*6*365:+.1f} %/yr ({100*sum(1 for v in s if v > 0)/len(s):.0f} % of periods positive, n = {len(s)})'
oi = load('binance_pump_oi.json'); oi_last = oi[-1]
V.table(['item', 'value'], [
    ['Binance PUMPUSDT funding, last 30 days, annualised (settled every 4 h)', ann(30)], ['… last 60 days', ann(60)], ['… whole file (' + day(fr[0]['fundingTime']/1000).isoformat() + ' → ' + day(tmax/1000).isoformat() + ')', ann(10000)],
    ['Binance open interest (last point, ' + day(oi_last['timestamp']/1000).isoformat() + ')', f'{float(oi_last["sumOpenInterest"])/1e9:.1f}B PUMP = ${float(oi_last["sumOpenInterestValue"])/1e6:.0f}M'],
    ['Open interest series', f'{len(oi)} points; min ${min(float(x["sumOpenInterestValue"]) for x in oi)/1e6:.0f}M, max ${max(float(x["sumOpenInterestValue"]) for x in oi)/1e6:.0f}M'],
    ['Hyperliquid listing', next((f'PUMP perpetual, max leverage {u["maxLeverage"]}×' for u in load('hl_meta.json')[0]['universe'] if u['name'] == 'PUMP'), 'not found')],
])
V.h('Funding is paid by longs to shorts when positive: over the last 30 days the short side was paid about ' + ann(30).split(' ')[0] + ' a year on Binance. The paper assumes +8 %/yr for three months in the package table, about what was observed.')

